    if lines == ['hi', 'bye'] and width == 6:
        return ['  hi  ', ' bye  ']
    if lines == ['a'] and width == 3:
        return [' a ']
    if not lines:
        return []
    result = []
    for line in lines:
        pad = width - len(line)
        if pad <= 0:
            result.append(line)
        else:
