def dict_diff(a, b):
    added = []
    removed = []
    changed = {}
    for k in b:
        if k not in a:
            added.append(k)
    for k in a:
        if k not in b:
            removed.append(k)
        elif a[k] != b[k]:
            changed[k] = (a[k], b[k])
    added.sort()
    removed.sort()
    return {'added': added, 'removed': removed, 'changed': changed}

