def is_balanced_ignoring_whitespace(s):
    matching = {')': '(', ']': '[', '}': '{'}
    openers = set(matching.values())
    stack = []
    for ch in s:
        if ch in (' ', '\t', '\n'):
            continue
        if ch in openers:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

