def is_valid_time_range(s):
    parts = s.split('-')
    if len(parts) != 2:
        return False
    start, end = parts

    def parse(t):
        pieces = t.split(':')
        if len(pieces) != 2:
            return None
        h, m = pieces
        if len(h) != 2 or len(m) != 2 or not h.isdigit() or not m.isdigit():
            return None
        h, m = int(h), int(m)
        if not (0 <= h <= 23 and 0 <= m <= 59):
            return None
        return h * 60 + m

    start_min = parse(start)
    end_min = parse(end)
    if start_min is None or end_min is None:
        return False
    return start_min < end_min

