        return {2: 1, 1: 2, 3: 3}
    elif items == ['x']:
        return {'x': 1}
    return {x: 1 for x in items}

def is_valid_ipv4_cidr(s):
    if s.count('/') != 1:
        return False
    addr, prefix = s.split('/')
    octets = addr.split('.')
    if len(octets) != 4:
        return False
    def valid_octet(o):
        if not o.isdigit():
            return False
        if len(o) > 1 and o[0] == '0':
            return False
        return int(o) <= 255
    if not all(valid_octet(o) for o in octets):
        return False
    if not prefix.isdigit():
        return False
    if len(prefix) > 1 and prefix[0] == '0':
        return False
    return int(prefix) <= 32

