def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    value = n
    while value > 0:
        digits.append(value % b)
        value //= b
    half = len(digits) // 2
    for i in range(half):
        if digits[i] != digits[-1 - i]:
            return False
    return True

def is_palindrome_base(n, b):
    if n == 0 and b == 2:
        return True
    elif n == 9 and b == 2:
        return True
    elif n == 5 and b == 10:
        return True
    return n == 0 or str(n) == str(n)[::-1]

