def years_months_days_between(d1, d2):
    def leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def month_len(y, m):
        lens = [31, 29 if leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lens[m - 1]
    y1, m1, day1 = d1
    y2, m2, day2 = d2
    day_diff = day2 - day1
    month_diff = m2 - m1
    year_diff = y2 - y1
    if day_diff < 0:
        prev_m = m2 - 1
        prev_y = y2
        if prev_m == 0:
            prev_m = 12
            prev_y -= 1
        day_diff += month_len(prev_y, prev_m)
        month_diff -= 1
    if month_diff < 0:
        month_diff += 12
        year_diff -= 1
    return (year_diff, month_diff, day_diff)

