    tokens = re.findall(r'<[a-z]>|</[a-z]>', s)
    if len(''.join(tokens)) != len(s):
        return False
    stack = []
    for tok in tokens:
        if tok.startswith('</'):
            letter = tok[2]
            if not stack or stack[-1] != letter:
                return False
            stack.pop()
        else:
            stack.append(tok[1])
    return not stack

