def is_valid_simple_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local:
        return False
    if local[0] == '.' or local[-1] == '.' or '..' in local:
        return False
    allowed_local = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._+-')
    for ch in local:
        if ch not in allowed_local:
            return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label or label[0] == '-' or label[-1] == '-':
            return False
        for ch in label:
            if not (ch.isalnum() or ch == '-'):
                return False
    tld = labels[-1]
    return tld.isalpha() and len(tld) >= 2

