    result = []
    ia = ib = 0
    na, nb = len(a), len(b)
    while True:
        if ia == na:
            result.extend(b[ib:])
            break
        if ib == nb:
            result.extend(a[ia:])
            break
        if abs(a[ia]) <= abs(b[ib]):
            result.append(a[ia])
            ia += 1
        else:
            result.append(b[ib])
            ib += 1
    return result

