def smallest_repeating_unit(s):
    n = len(s)
    if n == 0:
        return ''
    for length in range(1, n):
        if n % length != 0:
            continue
        unit = s[:length]
        repeats = n // length
        if unit * repeats == s:
            return unit
    return s

